// Host unit tests for lib/snmp_agent trap encoding. Expected bytes were generated by
// net-snmp's snmptrap with the same fields, so these are byte-for-byte compatibility tests.
// Run: pio test -e native -f native/test_snmp_trap

#include <unity.h>
#include <string.h>
#include <snmp_trap.h>

void setUp() {}
void tearDown() {}

static const uint8_t AGENT[4] = {10, 10, 6, 111};

// snmptrap -v1 -c public <host> 1.3.6.1.4.1.63050 10.10.6.111 6 1 12345
//   1.3.6.1.4.1.63050.1.0 i 0  1.3.6.1.4.1.63050.2.0 c 1  1.3.6.1.4.1.63050.3.0 t 12345
static const uint8_t NETSNMP_MAINS_LOST[] = {
    0x30, 0x5d, 0x02, 0x01, 0x00, 0x04, 0x06, 0x70, 0x75, 0x62, 0x6c, 0x69, 0x63, 0xa4, 0x50, 0x06,
    0x08, 0x2b, 0x06, 0x01, 0x04, 0x01, 0x83, 0xec, 0x4a, 0x40, 0x04, 0x0a, 0x0a, 0x06, 0x6f, 0x02,
    0x01, 0x06, 0x02, 0x01, 0x01, 0x43, 0x02, 0x30, 0x39, 0x30, 0x34, 0x30, 0x0f, 0x06, 0x0a, 0x2b,
    0x06, 0x01, 0x04, 0x01, 0x83, 0xec, 0x4a, 0x01, 0x00, 0x02, 0x01, 0x00, 0x30, 0x0f, 0x06, 0x0a,
    0x2b, 0x06, 0x01, 0x04, 0x01, 0x83, 0xec, 0x4a, 0x02, 0x00, 0x41, 0x01, 0x01, 0x30, 0x10, 0x06,
    0x0a, 0x2b, 0x06, 0x01, 0x04, 0x01, 0x83, 0xec, 0x4a, 0x03, 0x00, 0x43, 0x02, 0x30, 0x39};

// snmptrap -v1 -c public <host> 1.3.6.1.4.1.63050 10.10.6.111 0 0 42
static const uint8_t NETSNMP_COLD_START[] = {
    0x30, 0x28, 0x02, 0x01, 0x00, 0x04, 0x06, 0x70, 0x75, 0x62, 0x6c, 0x69, 0x63, 0xa4, 0x1b, 0x06,
    0x08, 0x2b, 0x06, 0x01, 0x04, 0x01, 0x83, 0xec, 0x4a, 0x40, 0x04, 0x0a, 0x0a, 0x06, 0x6f, 0x02,
    0x01, 0x00, 0x02, 0x01, 0x00, 0x43, 0x01, 0x2a, 0x30, 0x00};

static SnmpDeviceState mainsState(bool present, uint32_t changes, uint32_t lastChange) {
    SnmpDeviceState s;
    memset(&s, 0, sizeof(s));
    s.uptimeTicks = lastChange + 500;
    s.mainsPresent = present;
    s.mainsChanges = changes;
    s.mainsLastChangeTicks = lastChange;
    return s;
}

static void test_mains_lost_trap_matches_netsnmp_byte_for_byte() {
    uint8_t buf[256];
    size_t len = snmpBuildMainsTrap("public", AGENT, mainsState(false, 1, 12345), buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(sizeof(NETSNMP_MAINS_LOST), len);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(NETSNMP_MAINS_LOST, buf, sizeof(NETSNMP_MAINS_LOST));
}

static void test_cold_start_trap_matches_netsnmp_byte_for_byte() {
    uint8_t buf[128];
    size_t len = snmpBuildColdStartTrap("public", AGENT, 42, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(sizeof(NETSNMP_COLD_START), len);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(NETSNMP_COLD_START, buf, sizeof(NETSNMP_COLD_START));
}

static void test_auth_failure_trap_differs_from_cold_start_only_in_generic_type() {
    uint8_t buf[128];
    size_t len = snmpBuildAuthFailureTrap("public", AGENT, 42, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_size_t(sizeof(NETSNMP_COLD_START), len);
    uint8_t expected[sizeof(NETSNMP_COLD_START)];
    memcpy(expected, NETSNMP_COLD_START, sizeof(expected));
    expected[33] = 4;  // generic-trap: authenticationFailure
    TEST_ASSERT_EQUAL_HEX8_ARRAY(expected, buf, sizeof(expected));
}

/// Decode the PDU fields of a trap
struct DecodedTrap {
    Oid enterprise;
    const uint8_t* addr;
    int32_t generic, specific;
    uint32_t timestamp;
    uint8_t count;
    Oid names[SNMP_TRAP_MAX_VARBINDS];
    uint8_t tags[SNMP_TRAP_MAX_VARBINDS];
    int32_t ints[SNMP_TRAP_MAX_VARBINDS];
    uint32_t uints[SNMP_TRAP_MAX_VARBINDS];
};

static DecodedTrap decode(const uint8_t* buf, size_t len) {
    DecodedTrap d;
    memset(&d, 0, sizeof(d));
    BerReader top(buf, len), msg, pdu, list, vb;
    int32_t version;
    const uint8_t* s;
    size_t slen;
    TEST_ASSERT_TRUE(top.readSequence(BerTag::Sequence, msg));
    TEST_ASSERT_TRUE(msg.readInteger(version));
    TEST_ASSERT_TRUE(msg.readOctetString(s, slen));
    TEST_ASSERT_TRUE(msg.readSequence(BerTag::Trap, pdu));
    TEST_ASSERT_TRUE(pdu.readOid(d.enterprise));
    TEST_ASSERT_TRUE(pdu.readOctetString(d.addr, slen, BerTag::IpAddress));
    TEST_ASSERT_EQUAL_size_t(4, slen);
    TEST_ASSERT_TRUE(pdu.readInteger(d.generic));
    TEST_ASSERT_TRUE(pdu.readInteger(d.specific));
    TEST_ASSERT_TRUE(pdu.readUnsigned(BerTag::TimeTicks, d.timestamp));
    TEST_ASSERT_TRUE(pdu.readSequence(BerTag::Sequence, list));
    TEST_ASSERT_TRUE(pdu.atEnd());
    while (list.remaining() > 0) {
        uint8_t i = d.count++;
        TEST_ASSERT_TRUE(list.readSequence(BerTag::Sequence, vb));
        TEST_ASSERT_TRUE(vb.readOid(d.names[i]));
        TEST_ASSERT_TRUE(vb.peekTag(d.tags[i]));
        if (d.tags[i] == BerTag::Integer) {
            TEST_ASSERT_TRUE(vb.readInteger(d.ints[i]));
        } else {
            TEST_ASSERT_TRUE(vb.readUnsigned(d.tags[i], d.uints[i]));
        }
    }
    TEST_ASSERT_TRUE(list.atEnd());
    return d;
}

static void test_mains_restored_trap_fields() {
    uint8_t buf[256];
    size_t len = snmpBuildMainsTrap("public", AGENT, mainsState(true, 2, 99000), buf, sizeof(buf));
    DecodedTrap d = decode(buf, len);
    TEST_ASSERT_EQUAL_INT32(6, d.generic);
    TEST_ASSERT_EQUAL_INT32((int32_t)MainsTrap::PowerRestored, d.specific);
    TEST_ASSERT_EQUAL_UINT32(99000, d.timestamp);
    TEST_ASSERT_EQUAL_HEX8_ARRAY(AGENT, d.addr, 4);
    TEST_ASSERT_EQUAL_UINT8(3, d.count);
    TEST_ASSERT_EQUAL_INT32(1, d.ints[0]);
    TEST_ASSERT_EQUAL_UINT32(2, d.uints[1]);
    TEST_ASSERT_EQUAL_UINT32(99000, d.uints[2]);
}

static void test_trap_varbinds_are_the_mib_objects() {
    uint8_t buf[256];
    DecodedTrap d = decode(buf, snmpBuildMainsTrap("public", AGENT, mainsState(false, 5, 7), buf, sizeof(buf)));
    for (uint8_t i = 0; i < 3; i++) {
        Oid expected = {{1, 3, 6, 1, 4, 1, 63050, (uint32_t)i + 1, 0}, 9};
        TEST_ASSERT_EQUAL(0, oidCompare(expected, d.names[i]));
        TEST_ASSERT_NOT_NULL(mibFind(d.names[i]));
    }
    TEST_ASSERT_EQUAL_HEX8(BerTag::Integer, d.tags[0]);
    TEST_ASSERT_EQUAL_HEX8(BerTag::Counter32, d.tags[1]);
    TEST_ASSERT_EQUAL_HEX8(BerTag::TimeTicks, d.tags[2]);
}

static void test_trap_uses_configured_community() {
    uint8_t buf[256];
    size_t len = snmpBuildColdStartTrap("s3cret", AGENT, 1, buf, sizeof(buf));
    BerReader top(buf, len), msg;
    int32_t v;
    const uint8_t* s;
    size_t slen;
    TEST_ASSERT_TRUE(top.readSequence(BerTag::Sequence, msg));
    TEST_ASSERT_TRUE(msg.readInteger(v));
    TEST_ASSERT_TRUE(msg.readOctetString(s, slen));
    TEST_ASSERT_EQUAL_size_t(6, slen);
    TEST_ASSERT_EQUAL_MEMORY("s3cret", s, 6);
}

static void test_trap_fails_cleanly() {
    uint8_t buf[256];
    TEST_ASSERT_EQUAL_size_t(0, snmpBuildColdStartTrap("public", AGENT, 1, buf, 20));   // too small
    TEST_ASSERT_EQUAL_size_t(0, snmpBuildColdStartTrap(nullptr, AGENT, 1, buf, sizeof(buf)));
    SnmpTrap t;
    memset(&t, 0, sizeof(t));
    t.community = "public";
    oidFromString("1.3.6.1.4.1.63050", t.enterprise);
    t.varbindCount = SNMP_TRAP_MAX_VARBINDS + 1;
    TEST_ASSERT_EQUAL_size_t(0, snmpBuildTrap(t, buf, sizeof(buf)));
}

// ---- throttle ----

static void test_throttle_allows_first_then_one_per_interval() {
    TrapThrottle t(10000);
    TEST_ASSERT_TRUE(t.allow(5));
    TEST_ASSERT_FALSE(t.allow(6));
    TEST_ASSERT_FALSE(t.allow(10004));
    TEST_ASSERT_EQUAL_UINT32(2, t.suppressed());
    TEST_ASSERT_TRUE(t.allow(10005));
    TEST_ASSERT_EQUAL_UINT32(0, t.suppressed());
}

static void test_throttle_first_event_at_time_zero_is_allowed() {
    TrapThrottle t(10000);
    TEST_ASSERT_TRUE(t.allow(0));
    TEST_ASSERT_FALSE(t.allow(1));
}

static void test_throttle_survives_millis_wraparound() {
    TrapThrottle t(10000);
    TEST_ASSERT_TRUE(t.allow(0xFFFFFFFFu - 100));
    TEST_ASSERT_FALSE(t.allow(50));          // 151 ms later, across the wrap
    TEST_ASSERT_TRUE(t.allow(10000));        // 10101 ms later
}

int main() {
    UNITY_BEGIN();
    RUN_TEST(test_mains_lost_trap_matches_netsnmp_byte_for_byte);
    RUN_TEST(test_cold_start_trap_matches_netsnmp_byte_for_byte);
    RUN_TEST(test_auth_failure_trap_differs_from_cold_start_only_in_generic_type);
    RUN_TEST(test_mains_restored_trap_fields);
    RUN_TEST(test_trap_varbinds_are_the_mib_objects);
    RUN_TEST(test_trap_uses_configured_community);
    RUN_TEST(test_trap_fails_cleanly);
    RUN_TEST(test_throttle_allows_first_then_one_per_interval);
    RUN_TEST(test_throttle_first_event_at_time_zero_is_allowed);
    RUN_TEST(test_throttle_survives_millis_wraparound);
    return UNITY_END();
}
